import Redwood from '@redwood/inference'
const client = new Redwood()
// automatic idempotency header attach
await client.requests.createResource({ body, idempotencyKey: 'user-123-create-202603' })

// stream example with resume token
const s = await client.streams.start({ uploadId: 'file-xyz' })
for await (const chunk of chunks) {
  const res = await s.send(chunk)
  if (res.resumeToken) localStorage.setItem('resume', res.resumeToken)
}
const token = localStorage.getItem('resume')
if (token) await client.streams.resume({ uploadId: 'file-xyz', resumeToken: token })

cli := redwood.NewClient()
// idemp through context
ctx := redwood.WithIdempotency(context.Background(), 'user-123-create-202603')
err := cli.CreateResource(ctx, payload)

// stream resume
stream, _ := cli.StartStream(ctx, 'file-xyz')
for scanner.Scan() {
  chunk := scanner.Bytes()
  resp, _ := stream.Send(chunk)
  if resp.Checkpoint != "" { persist(resp.Checkpoint) }
}
checkpoint := loadPersisted()
if checkpoint != "" { cli.ResumeStream(ctx, 'file-xyz', checkpoint) }
